import sys

def is_prime(n):
    """Check if a number is prime."""
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return False
    return True

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    tiles = list(map(int, data[1:1+n]))

    # Count the number of 1s and 2s
    count_1 = tiles.count(1)
    count_2 = tiles.count(2)

    # Strategy: start with 2 if available, then alternate
    if count_2 > 0:
        # Start with 2
        result = [2]
        count_2 -= 1

        # Alternate between 1 and 2
        while count_1 > 0 and count_2 > 0:
            result.append(1)
            count_1 -= 1
            result.append(2)
            count_2 -= 1

        # Add remaining 1s
        while count_1 > 0:
            result.append(1)
            count_1 -= 1
    else:
        # No 2s, just output all 1s
        result = [1] * n

    print(' '.join(map(str, result)))

if __name__ == "__main__":
    solve()
"}

