def count_multiples(arr, l, r, value):
    """Count how many elements in arr[l:r+1] are multiples of value"""
    count = 0
    for i in range(l, r + 1):
        if arr[i] % value == 0:
            count += 1
    return count

n = int(input())
s = list(map(int, input().split()))
t = int(input())

for _ in range(t):
    l, r = map(int, input().split())
    total_ants = r - l + 1

    # Count frequency of each value in the range
    freq = {}
    for i in range(l, r + 1):
        val = s[i]
        freq[val] = freq.get(val, 0) + 1

    # For each ant, count how many points it gets
    points = [0] * (r - l + 1)

    # Count points from other ants with the same value
    for val, count in freq.items():
        for i in range(l, r + 1):
            if s[i] == val:
                points[i - l] += count - 1  # Points from other ants with the same value

    # Count points from ants with different values
    for i in range(l, r + 1):
        val = s[i]
        points[i - l] += count_multiples(s, l, r, val)

    # Count how many ants are freed
    freed = 0
    for p in points:
        if p == total_ants - 1:
            freed += 1

    # Output how many ants are eaten
    print(total_ants - freed)
