def longest_path(n, edges):
    # Build adjacency list
    adj = [[] for _ in range(n + 1)]
    for a, b in edges:
        adj[a].append(b)
        adj[b].append(a)

    # dp[mask][u] = length of longest path ending at u with visited nodes in mask
    dp = [[-1] * (n + 1) for _ in range(1 << n)]

    # Initialize: single node paths
    for u in range(1, n + 1):
        dp[1 << (u - 1)][u] = 1

    max_len = 1

    # Try all masks
    for mask in range(1 << n):
        for u in range(1, n + 1):
            if not (mask & (1 << (u - 1))):
                continue

            # Try to extend the path
            for v in adj[u]:
                if mask & (1 << (v - 1)):
                    continue

                new_mask = mask | (1 << (v - 1))
                if dp[new_mask][v] < dp[mask][u] + 1:
                    dp[new_mask][v] = dp[mask][u] + 1

                max_len = max(max_len, dp[new_mask][v])

    return max_len

# Read input
import sys

for line in sys.stdin:
    n = int(line.strip())
    if n == 0:
        break

    edges = []
    for _ in range(n):
        a, b = map(int, sys.stdin.readline().strip().split())
        edges.append((a, b))

    result = longest_path(n, edges)
    print(result)
