def compute_grundy(L, k, memo):
    if L < k:
        return 0
    if L in memo:
        return memo[L]

    # Find all valid splits
    moves = set()
    for d in range(2, L + 1):
        if L % d == 0:
            part_length = L // d
            if part_length >= k:
                moves.add(compute_grundy(part_length, k, memo))

    # Compute mex
    mex = 0
    while mex in moves:
        mex += 1

    memo[L] = mex
    return mex

def solve():
    n, m, k = map(int, input().split())

    # Compute Grundy number for a single log of length m
    memo = {}
    g = compute_grundy(m, k, memo)

    # If Grundy number is non-zero, Timur wins; otherwise, Marsel wins
    if g != 0:
        print("Timur")
    else:
        print("Marsel")

solve()
