        if L % d == 0:
            part_length = L // d
            if part_length >= k:
                # Compute XOR of d parts of length part_length
                if d % 2 == 1:
                    # Odd number of parts, XOR is g(part_length)
                    moves.add(compute_grundy(part_length, k, memo))
