def distance(p1, p2):
    """Calculate Euclidean distance between two points"""
    return math.sqrt((p1[0] - p2[0])**2 + (p1[1] - p2[1])**2)

def solve():
    data = []
    n = int(input())

    for _ in range(n):
        x, y, f = map(int, input().split())
        data.append((x, y, f))

    # dp[i] = max happiness ending at city i (0-indexed)
    dp = [0] * n
    dp[0] = data[0][2]  # Start at city 0

    for i in range(1, n):
        max_happiness = -float('inf')
        for j in range(i):
            # Happiness from going from city j to city i
            happiness = dp[j] + data[i][2] - distance(data[j], data[i])
            if happiness > max_happiness:
                max_happiness = happiness
        dp[i] = max_happiness

    print(f"{dp[n-1]:.6f}")

solve()
