import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    count_1 = a.count(1)
    count_2 = a.count(2)

    if count_2 == 0:
        # All are 1s, output them in any order
        print(' '.join(map(str, a)))
    else:
        # Start with 1, then all 1s, then remaining 2s
        result = [1] + [1] * (count_1 - 1) + [2] * count_2
        print(' '.join(map(str, result)))

if __name__ == "__main__":
    solve()
"}

