import sys

def starts_with(s, prefix):
    return s.startswith(prefix)

def ends_with(s, suffix):
    return s.endswith(suffix)

def solve():
    data = sys.stdin.read().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    q = int(next(it))

    words = []
    for _ in range(n):
        words.append(next(it))

    out_lines = []
    for _ in range(q):
        p = next(it)
        s = next(it)
        count = 0
        for word in words:
            if starts_with(word, p) and ends_with(word, s):
                count += 1
        out_lines.append(str(count))

    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()
"}

