import sys

def is_valid_integer(word):
    """Check if a word is a valid nonnegative integer without leading zeroes"""
    if not word:
        return False
    if word[0] == '0' and len(word) > 1:
        return False
    return all(c.isdigit() for c in word)

def main():
    s = sys.stdin.read().strip()

    # Split into words by splitting on ',' and ';'
    words = []
    current_word = ''

    for char in s:
        if char in ",;":
            words.append(current_word)
            current_word = ''
        else:
            current_word += char
    # Add the last word
    words.append(current_word)

    # Separate into number words and non-number words
    number_words = []
    non_number_words = []

    for word in words:
        if is_valid_integer(word):
            number_words.append(word)
        else:
            non_number_words.append(word)

    # Build strings a and b
    a = ','.join(number_words)
    b = ','.join(non_number_words)

    # Output
    if a:
        print(f"{a}")
    else:
        print('-')

    if b:
        print(f"{b}")
    else:
        print('-')

if __name__ == '__main__':
    main()
