# Read input
t = int(input())

for _ in range(t):
    # Read k and protein values
    parts = input().split()
    k = int(parts[0])
    protein_values = list(map(int, parts[1:1+k]))

    # Read ingredient sequence
    ingredients = input().strip()

    # Read target protein
    s = int(input())

    # Map ingredient to protein value
    protein_map = {chr(ord('a') + i): protein_values[i] for i in range(k)}

    # Dynamic programming: dp[s] = lexicographically smallest subsequence with sum s
    # We'll use a dictionary to store the smallest subsequence for each sum
    dp = {0: ""}

    for char in ingredients:
        # Get protein value of current character
        p = protein_map[char]

        # Create a new temporary dictionary to store updates
        temp = {}

        # Iterate through existing sums in reverse order
        for current_sum in list(dp.keys()):
            current_seq = dp[current_sum]

            # Calculate new sum
            new_sum = current_sum + p

            # Update the temporary dictionary
            if new_sum not in temp:
                temp[new_sum] = current_seq + char
            else:
                # Choose lexicographically smaller option
                temp[new_sum] = min(temp[new_sum], current_seq + char)

        # Merge temporary updates into dp
        for new_sum, new_seq in temp.items():
            if new_sum not in dp:
                dp[new_sum] = new_seq
            else:
                dp[new_sum] = min(dp[new_sum], new_seq)

    # Check if target sum is achievable
    if s in dp:
        print(dp[s])
    else:
        print("IMPOSSIBLE")
