import sys

def find_cycle(graph, n):
    """Find a cycle in the graph"""
    for start in range(1, n + 1):
        if start not in graph:
            continue  # Skip vertices with no outgoing edges

        visited = set()
        current = start
        path = []

        while current not in visited:
            visited.add(current)
            path.append(current)

            # If current has no outgoing edge, we can't continue
            if current not in graph:
                break
            current = graph[current]

        if current in path:
            # Found a cycle
            cycle_start = path.index(current)
            cycle = path[cycle_start:]
            return cycle

    return None

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    idx = 0
    n = int(data[idx])
    idx += 1
    m = int(data[idx])
    idx += 1

    graph = {}
    for _ in range(m):
        a = int(data[idx])
        idx += 1
        b = int(data[idx])
        idx += 1
        graph[a] = b

    cycle = find_cycle(graph, n)

    if cycle:
        print(len(cycle))
        for v in cycle:
            print(v)
    else:
        print(-1)

if __name__ == "__main__":
    main()
