def is_beneficial(i):
    """Determine if operation i is beneficial"""
    if i == 1:
        return True

    # Get prime factorization
    factors = {}
    temp = i
    for p in range(2, int(temp**0.5) + 1):
        while temp % p == 0:
            factors[p] = factors.get(p, 0) + 1
            temp //= p

    if temp > 1:
        factors[temp] = 1

    # Find p_max
    max_exp = max(factors.values())
    candidates = [p for p, exp in factors.items() if exp == max_exp]
    p_max = min(candidates)

    return (p_max % i) % 2 == 1

def solve():
    import sys
    input = sys.stdin.read().split()

    if not input:
        return

    N = int(input[0])
    L = int(input[1])
    A = list(map(int, input[2:2+N]))

    # Sort array
    A.sort()

    for i in range(1, L + 1):
        if i > len(A):
            break

        if is_beneficial(i):
            # Double the largest element
            A[-1] *= 2
        else:
            # Divide the smallest element by 2
            A[0] //= 2

        # Remove zeros
        A = [x for x in A if x != 0]

    print(len(A))
    if A:
        print(' '.join(map(str, A)))

solve()
