def is_beneficial(i):
    """Determine if operation i is beneficial"""
    if i == 1:
        return True

    # Get prime factorization using trial division
    factors = {}
    temp = i

    # Check for even factor
    if temp % 2 == 0:
        while temp % 2 == 0:
            factors[2] = factors.get(2, 0) + 1
            temp //= 2

    # Check for odd factors
    p = 3
    while p * p <= temp:
        if temp % p == 0:
            while temp % p == 0:
                factors[p] = factors.get(p, 0) + 1
                temp //= p
        p += 2

    # If remaining is prime
    if temp > 1:
        factors[temp] = 1

    # Find p_max
    max_exp = max(factors.values())
    candidates = [p for p, exp in factors.items() if exp == max_exp]
