def max_overlap(a, b):
    """Calculate the maximum overlap where suffix of a matches prefix of b"""
    max_overlap = 0
    for i in range(1, min(len(a), len(b)) + 1):
        if a[-i:] == b[:i]:
            max_overlap = i
    return max_overlap

def solve():
    while True:
        n = int(input())
        if n == 0:
            break

        cities = []
        for _ in range(n):
            cities.append(input().strip())

        # Calculate overlaps between all pairs
        overlap = [[0] * n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if i != j:
                    overlap[i][j] = max_overlap(cities[i], cities[j])

        # DP: dp[mask][i] = minimum length to cover all cities in mask with i as last city
        dp = [[float('inf')] * n for _ in range(1 << n)]

        # Initialize: start with each city alone
        for i in range(n):
            dp[1 << i][i] = len(cities[i])

        # Fill DP table
        for mask in range(1 << n):
            for last in range(n):
                if not (mask & (1 << last)):
                    continue

                # Try adding each other city
                for next_city in range(n):
                    if mask & (1 << next_city):
                        continue

                    new_mask = mask | (1 << next_city)
                    new_len = dp[mask][last] + len(cities[next_city]) - overlap[last][next_city]

                    if new_len < dp[new_mask][next_city]:
                        dp[new_mask][next_city] = new_len

        # Find the minimum length covering all cities
        result = min(dp[(1 << n) - 1][i] for i in range(n))
        print(result)

solve()
