MOD = 1000000007

# Precompute factorials and inverse factorials up to 10^5
max_n = 100000
fact = [1] * (max_n + 1)
invc = [1] * (max_n + 1)

for i in range(1, max_n + 1):
    fact[i] = fact[i-1] * i % MOD

inv_fact = [1] * (max_n + 1)
inv_fact[max_n] = pow(fact[max_n], MOD-2, MOD)
for i in range(max_n-1, -1, -1):
    inv_fact[i] = inv_fact[i+1] * (i+1) % MOD


def comb(n, k):
    """Compute combination C(n, k) modulo MOD"""
    if n < 0 or k < 0 or k > n:
        return 0
    return fact[n] * inv_fact[k] % MOD * inv_fact[n - k] % MOD

# Function to find all divisors of n > 1
def get_divisors(n):
    divisors = []
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            divisors.append(i)
            if i != n // i:
                divisors.append(n // i)
    if n > 1:
        divisors.append(n)
    return sorted(divisors)

q = int(input())
for _ in range(q):
    n, f = map(int, input().split())

    # Total compositions
    total = comb(n-1, f-1)

    # Subtract compositions where all parts have a common divisor > 1
    divisors = get_divisors(n)
    subtract = 0
    for d in divisors:
        subtract = (subtract + comb((n//d)-1, f-1)) % MOD

    ans = (total - subtract) % MOD
    print(ans)
"}

